exercises.solution:
def char_types(text):
    counts = {"letters": 0, "digits": 0, "others": 0}
    for ch in text:
        if ch.isalpha():
            counts["letters"] += 1
        elif ch.isdigit():
            counts["digits"] += 1
        else:
            counts["others"] += 1
    return counts

