exercises.solution:
def group_anagrams(words):
    groups = {}
    for w in words:
        key = "".join(sorted(w))
        if key not in groups:
            groups[key] = []
        groups[key].append(w)
    result = []
    for group in groups.values():
        if len(group) > 1:
            result.append(group)
    return result
